import {
  separateCompactClips,
  type DecodedClip,
  type SeparationProgress,
  type CompactSeparationResult,
} from '../lib/separation'

export type SeparationWorkerRequest =
  { type: 'start'; model: Blob; clips: DecodedClip[] }

export type SeparationWorkerResponse =
  | ({ type: 'progress' } & SeparationProgress)
  | { type: 'completed'; results: CompactSeparationResult[] }
  | { type: 'error'; message: string }

interface WorkerScope {
  onmessage: ((event: MessageEvent<SeparationWorkerRequest>) => void) | null
  postMessage(message: SeparationWorkerResponse, transfer?: Transferable[]): void
}

const workerScope = self as unknown as WorkerScope

function resultTransfer(result: CompactSeparationResult): Transferable[] {
  return [
    result.bass.left.buffer,
    result.bass.right.buffer,
    result.drums.left.buffer,
    result.drums.right.buffer,
    result.vocals.left.buffer,
    result.vocals.right.buffer,
    result.other.left.buffer,
    result.other.right.buffer,
  ]
}

function reportError(reason: unknown): void {
  workerScope.postMessage({
    type: 'error',
    message: reason instanceof Error ? reason.message : '背景 AI 分離失敗。',
  })
}

workerScope.onmessage = (event) => {
  const request = event.data
  void separateCompactClips(request.model, request.clips, (progress) => {
    workerScope.postMessage({ type: 'progress', ...progress })
  }).then((results) => {
    workerScope.postMessage({ type: 'completed', results }, results.flatMap(resultTransfer))
  }).catch(reportError)
}
